def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    comp = s.get('composition') or {}
    fractions = [x for x in comp.values() if x is not None and x > 0]
    norm = sum(fractions)
    expected = 1.0 - sum((x / norm) ** 2 for x in fractions) if norm > 0 else 0.0
    if expected <= 0:
        return 0.0
    occ = [max(0.0, t.get('occupancy')) if t.get('occupancy') is not None else 1.0 for t in sites]
    near = [1000000.0 for t in sites]
    bonds = s.get('neighbors') or []
    for b in bonds:
        i = b.get('i')
        d = b.get('distance_A')
        if i is not None and 0 <= i < n and d is not None and d > 0:
            near[i] = min(near[i], d)
    hetero = 0.0
    total = 0.0
    for b in bonds:
        i = b.get('i')
        j = b.get('j')
        d = b.get('distance_A')
        if i is None or j is None or d is None:
            continue
        if 0 <= i < n and 0 <= j < n and 0 < d <= 1.25 * near[i]:
            w = occ[i] * occ[j]
            total += w
            if sites[i].get('element') != sites[j].get('element'):
                hetero += w
    return float(hetero / (total * expected)) if total > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    en = [(props.get(t.get('element')) or {}).get('eneg') for t in sites]
    values = [v for v in en if v is not None]
    if not values:
        return 0.0
    mean = sum(values) / len(values)
    variance = sum((v - mean) ** 2 for v in values) / len(values)
    if variance <= 0:
        return 0.0
    bonds = s.get('neighbors') or []
    near = [1000000.0 for t in sites]
    for b in bonds:
        i = b.get('i')
        d = b.get('distance_A')
        if i is not None and 0 <= i < n and d is not None and d > 0:
            near[i] = min(near[i], d)
    total = 0.0
    weight = 0.0
    for b in bonds:
        i = b.get('i')
        j = b.get('j')
        d = b.get('distance_A')
        if i is None or j is None or d is None:
            continue
        if 0 <= i < n and 0 <= j < n and 0 < d <= 1.25 * near[i]:
            if en[i] is not None and en[j] is not None:
                total += (en[i] - mean) * (en[j] - mean) / d
                weight += 1.0 / d
    return float(total / (weight * variance)) if weight > 0 else 0.0

def feature(s):
    s = s or {}
    comp = s.get('composition') or {}
    props = s.get('element_properties') or {}
    numerator = 0.0
    denominator = 0.0
    weight = 0.0
    for el, x in comp.items():
        p = props.get(el) or {}
        ion = p.get('first_ionization_energy_eV')
        ea = p.get('electron_affinity_eV')
        if x is None or x <= 0 or ion is None or ion <= 0:
            continue
        ea = 0.0 if ea is None else ea
        chi = 0.5 * (ion + ea)
        hardness = max(1.0, ion - ea)
        numerator += x * chi / hardness
        denominator += x / hardness
        weight += x
    if denominator <= 0 or weight <= 0:
        return 0.0
    mu = numerator / denominator
    total = 0.0
    for el, x in comp.items():
        p = props.get(el) or {}
        ion = p.get('first_ionization_energy_eV')
        ea = p.get('electron_affinity_eV')
        if x is None or x <= 0 or ion is None or ion <= 0:
            continue
        ea = 0.0 if ea is None else ea
        chi = 0.5 * (ion + ea)
        hardness = max(1.0, ion - ea)
        total += 0.5 * x * (chi - mu) ** 2 / hardness
    return float(total / weight)

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    if n == 0:
        return 0.0
    props = s.get('element_properties') or {}
    occ = [max(0.0, t.get('occupancy')) if t.get('occupancy') is not None else 1.0 for t in sites]
    chi = [0.0 for t in sites]
    hardness = [0.0 for t in sites]
    numerator = 0.0
    denominator = 0.0
    for i in range(n):
        p = props.get(sites[i].get('element')) or {}
        ion = p.get('first_ionization_energy_eV')
        ea = p.get('electron_affinity_eV')
        if ion is None or ion <= 0:
            continue
        ea = 0.0 if ea is None else ea
        chi[i] = 0.5 * (ion + ea)
        hardness[i] = max(1.0, ion - ea)
        numerator += occ[i] * chi[i] / hardness[i]
        denominator += occ[i] / hardness[i]
    if denominator <= 0 or sum(occ) <= 0:
        return 0.0
    mu = numerator / denominator
    charge = [(mu - chi[i]) / hardness[i] if hardness[i] > 0 else 0.0 for i in range(n)]
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i')
        j = b.get('j')
        d = b.get('distance_A')
        if i is None or j is None or d is None or d <= 0:
            continue
        if 0 <= i < n and 0 <= j < n:
            total += occ[i] * occ[j] * charge[i] * charge[j] * float(np.exp(-d / 3.0)) / d
    return float(0.5 * total / sum(occ))

