def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    selected = [False for t in sites]
    for i in range(n):
        p = props.get(sites[i].get('element')) or {}
        group = p.get('group')
        en = p.get('eneg')
        selected[i] = group is not None and en is not None and 14 <= group <= 17 and en >= 2.0
    occ = [max(0.0, t.get('occupancy')) if t.get('occupancy') is not None else 1.0 for t in sites]
    near = [1000000.0 for t in sites]
    bonds = s.get('neighbors') or []
    for b in bonds:
        i = b.get('i')
        d = b.get('distance_A')
        if i is not None and 0 <= i < n and d is not None and d > 0:
            near[i] = min(near[i], d)
    total = 0.0
    connected = 0.0
    for b in bonds:
        i = b.get('i')
        j = b.get('j')
        d = b.get('distance_A')
        if i is None or j is None or d is None:
            continue
        if 0 <= i < n and 0 <= j < n and selected[i] and 0 < d <= 1.25 * near[i]:
            w = occ[i] * occ[j]
            total += w
            if selected[j]:
                connected += w
    return float(connected / total) if total > 0 else 0.0

def feature(s):
    s = s or {}
    v = s.get('volume_per_atom_A3')
    if v is not None and v > 0:
        return float(v)
    sites = s.get('sites') or []
    n = sum((a.get('occupancy', 1.0) or 0.0) for a in sites)
    lattice = s.get('lattice') or {}
    v = lattice.get('volume_A3')
    if v is None or n <= 0:
        return 0.0
    return float(v / n)

