def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    properties = s.get('element_properties') or {}
    total = 0.0
    atoms = 0.0
    for site in sites:
        p = properties.get(site.get('element')) or {}
        r = p.get('covalent_radius_A') or 1.3
        w = site.get('occupancy', 1.0) or 0.0
        total = total + w * r * r * r
        atoms = atoms + w
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        if v is None or v <= 0:
            return 0.0
        volume = v * atoms
    if volume <= 0:
        return 0.0
    return float(4.0 * pi * total / (3.0 * volume))

def feature(s):
